mapper.select:
SELECT id, goods_id, goods_code, goods_name, goods_spec, unit, warehouse_id, area_id, shelf_id, location_id, batch_no, production_date, shelf_life, expiry_date, quantity, locked_qty, in_detail_id, production_batch_id, supplier_id, supplier_name, stock_in_time, original_qty FROM mis_stock WHERE del_flag = '0' AND warehouse_id = #{warehouseId} AND goods_id = #{goodsId} AND (quantity - locked_qty) > 0
AND batch_no = #{batchNo}
ORDER BY stock_in_time ASC, create_time ASC

mapper.update:
UPDATE mis_stock
SET locked_qty = locked_qty + #{lockQty},
    update_time = NOW()
WHERE id = #{id}
  AND (quantity - locked_qty) >= #{lockQty}

UPDATE mis_stock
SET quantity = quantity - #{qty},
    locked_qty = locked_qty - #{qty},
    update_time = NOW()
WHERE id = #{id}
  AND locked_qty >= #{qty}

UPDATE mis_stock
SET locked_qty = locked_qty - #{lockQty},
    update_time = NOW()
WHERE id = #{id}
  AND locked_qty >= #{lockQty}

UPDATE mis_stock
SET quantity = quantity - #{qty},
    update_time = NOW()
WHERE id = #{id}
  AND (quantity - locked_qty) >= #{qty}

UPDATE mis_stock
SET quantity = quantity - #{qty},
    update_time = NOW()
WHERE id = #{id}
  AND quantity >= #{qty}
